---@type CatHouseMgr
local CatHouseMgr = import('Game.CatHouse.CatHouseMgr')
------------ import ------------

------------ define ------------
local SceneHandBookId = Constants.IdSceneSetting25 ---场景id
local ModelPositionName = "3DPosition"
local MainCameraName = "Main Camera"
local SwitchHandBookDataUI = 'SwitchHandBookDataUI'
local HandBookEnterAnimation = 'HandBookEnterAnimation'

local SwitchTypeInfo = {
    ['3'] = 1, ['1'] = 2, ['2'] = 3, ['4'] = 4
}

local AnimationKey = "GuideAnimation"

---@type ConstantsCatHouse
local ConstantsCatHouse = import("Game.CatHouse.ConstantsCatHouse")
