---@class CatHouseHandBookMain
---@field TxtNumber                        TMPro.TextMeshProUGUI @合卡技数量
---@field Txtstate                        UnityEngine.UI.Text @显示合卡技的
---@field ImgIcon                        UnityEngine.UI.Image
---@field ActivateProperties                UnityEngine.RectTransform
---@field BtnGroup4                        UnityEngine.RectTransform
---@field BtnGroup3                        UnityEngine.RectTransform
---@field BtnGroup2                        UnityEngine.RectTransform
---@field BtnGroup1                        UnityEngine.RectTransform @变异
local CatHouseHandBookMain = Class("CatHouseHandBookMain")

function CatHouseHandBookMain:__init()
    self._model2UIPosition = {}
    self.previewCatGo = nil
    self.cameraAnimator = nil
end

function CatHouseHandBookMain:__delete()
    self.previewCatGo = nil
    self.cameraAnimator = nil
    self._model2UIPosition = nil
    self.previewCatGo = nil
    self.controller = nil
end

function CatHouseHandBookMain:Awake()

    SetButtonAction(self.ActivateProperties.gameObject, function()
        ---已解锁的战中属性的信息
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        if #component:GetAllUnlockGenesAttributeAddition() > 0 then
            ----执行打开的显示面板的逻辑
            UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseHandbookAttributeAdditionDialog }, { { id = Constants.UITypeIds.CatHouseHandbookDialog } })
        else
            GameUtils.Toast(localize("暂时未存在解锁的战中加成属性"))
        end
    end)
end

---SetButtonAction
---@param sender UnityEngine.EventSystems.PointerEventData
function CatHouseHandBookMain:SetButtonAction(sender)
    ---@type Game.Native.Common.ID
    local idComp = KTool.GetComponent(sender.selectedObject.gameObject, typeof(ID))
    local id = idComp.id
    ---3 2 1 4 -->> 1 2 3 4
    UIRaycastBlocker:AddCondition(SwitchHandBookDataUI)
    cs_coroutine.start(function()
        if not isNull(self.previewCatGo) then
            ---@type Animancer.NamedAnimancerComponent
            local animator = KTool.GetComponent(self.previewCatGo, typeof(NamedAnimancerComponent))
            if animator and self.cameraAnimator then
                ---@type Animancer.AnimancerState
                local state = animator:TryPlay("move" .. SwitchTypeInfo[tostring(id)], 0.1)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(state.Duration))
                cs_coroutine.yield_return(self.cameraAnimator:Play(string.format('%s%d', AnimationKey, SwitchTypeInfo[tostring(id)]), -1))
                cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseHandbookDataDialog, parameters = { id = id } }, { { id = Constants.UITypeIds.CatHouseHandbookDialog } }))
            end
        end
        UIRaycastBlocker:RemoveCondition(SwitchHandBookDataUI)
    end)

end

function CatHouseHandBookMain:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---@type SceneManagement
        local sceneManagement = SceneManagement:GetInstance()
        ---@type SceneInstance
        local sceneInstance = sceneManagement:GetSceneInstance(SceneHandBookId)
        local go = sceneInstance:GetCacheObjectByName(ModelPositionName)
        local cameraObject = sceneInstance:GetCacheObjectByName(MainCameraName)
        sceneManagement:SetActive(SceneHandBookId, true)
        self.cameraAnimator = KTool.GetComponent(cameraObject, typeof(Animator))
        KTool.GetOrAddComponent(cameraObject, typeof(URPBaseCamera))
        if go then
            ---@type UnityEngine.Transform
            local transform = go.transform
            local t = { "Variantation", "Basic", "Composite", "Part" }
            for i, v in pairs(t) do
                local v1 = CfUtils.WorldPosition2UIPosition(transform:Find(v).position, UIModule.RootCanvas.transform)
                table.insert(self._model2UIPosition, Vector2.New(v1.x, v1.y))
            end
        end
        self.cameraAnimator:Play("Entry", -1)

        local uis = { self.BtnGroup1, self.BtnGroup2, self.BtnGroup3, self.BtnGroup4 }
        local ids = { ConstantsCatHouse.ScreenCatDataType.Variation, ConstantsCatHouse.ScreenCatDataType.Basic,
                      ConstantsCatHouse.ScreenCatDataType.Combination, ConstantsCatHouse.ScreenCatDataType.Part }
        local kinds = { CatHouseMgr.ConstantsCatHouse.ScreenCatDataType.Variation, CatHouseMgr.ConstantsCatHouse.ScreenCatDataType.Basic,
                        CatHouseMgr.ConstantsCatHouse.ScreenCatDataType.Combination, CatHouseMgr.ConstantsCatHouse.ScreenCatDataType.Part }
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        for i, v in pairs(uis) do
            ---@type UnityEngine.RectTransform
            local buttonGroupNode = v
            if buttonGroupNode then
                ---@type Game.Native.Common.ID
                local idComp = KTool.GetOrAddComponent(buttonGroupNode.gameObject, typeof(ID))
                idComp.id = ids[i]
                SetButtonAction(buttonGroupNode.gameObject, Bind(self, self.SetButtonAction))
                buttonGroupNode.anchoredPosition = self._model2UIPosition[i]
                local guiText = KTool.GetComponent(buttonGroupNode:Find("TxtName/ImgBgNumber/TxtNumber").gameObject, typeof(TextMeshProUGUI))
                local kind = kinds[i]
                local progress = component:GetUnlockGenesByKind(kind)
                local max = CatHouseMgr:GetInstance():GetAllSettingGenesByKind(kind)
                guiText.text = string.format('%d/%d', #progress, #max)
            end
        end

        local guiText = KTool.GetComponent(self.ActivateProperties:Find("ImgBgNumber/TxtNumber").gameObject, typeof(TextMeshProUGUI))
        local progress = component:GetAllUnlockGenesAttributeAddition()
        local max = CatHouseMgr:GetInstance():GetAllSettingGenesAttributeAddition()
        guiText.text = string.format('%d/%d', #progress, #max)
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if playerComponent.playerDojo.partyCatInfo and isSet(playerComponent.playerDojo.partyCatInfo, "catId") then
            ---加载一只猫
            local catInfo = playerComponent.playerDojo.partyCatInfo
            local sceneManagement = SceneManagement:GetInstance()
            local sceneInstance = sceneManagement:GetSceneInstance(Constants.IdSceneSetting25)
            if sceneInstance then
                local parentGo = sceneInstance:GetCacheObjectByName("CatModel")
                if not isNull(parentGo) then
                    local isStart = KCookie.Get(HandBookEnterAnimation)
                    KTool.DestroyGameObjectChildren(parentGo)
                    self.previewCatGo = nil
                    local isFinish = false
                    cs_coroutine.start(function()
                        cs_coroutine.yield_return(CS.Game.Native.Corder.AutoPNGWriter.LoadCatAsync(ConstantsCatHouse.BornType.Adult, tostring(catInfo.catId), false, catInfo.genes, parentGo, function(go)
                            ---@type UnityEngine.Transform
                            local trans = go.transform
                            go.name = tostring(catInfo.catId)
                            trans.position = Vector3.New(0, 0, 0)
                            trans.localRotation = Quaternion.Euler(0, 0, 0)
                            self.previewCatGo = go
                            if isNull(isStart) then
                                local animator = KTool.GetComponent(go, typeof(NamedAnimancerComponent))
                                if animator then
                                    animator:TryPlay("entrance", 0.1)
                                end
                            end
                            isFinish = true
                        end))
                    end)
                    while not isFinish do
                        cs_coroutine.yield_return(Yielders.EndOfFrame)
                    end
                    if isNull(isStart) then
                        cs_coroutine.yield_return(3)
                        KCookie.Set(HandBookEnterAnimation, "1")
                    end
                end
            end
        end
    end))
    return coWait
end

